```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <unordered_map>

using namespace std;

int main() {
    string filename, search_word;
    int count = 0;

    // Get the file name and search word from the user
    cout << "Enter the name of the text file: ";
    cin >> filename;

    cout << "Enter the search word: ";
    cin >> search_word;

    // Open the file for reading
    ifstream file(filename);

    if (!file) {
        cerr << "Error opening file: " << filename << endl;
        return 1;
    }

    // Read the file line by line and count occurrences
    unordered_map<string, int> word_count;
    string line;
    while (getline(file, line)) {
        // Split the line into words and update the count for the search word
        size_t pos = 0;
        string token;
        while ((pos = line.find(" ")) != string::npos) {
            token = line.substr(pos, pos + 1 - pos);
            line.erase(pos, pos + 1);
            if (token == search_word) {
                ++word_count[search_word];
                ++count;
            }
        }
        if (line == search_word) {
            ++word_count[search_word];
            ++count;
        }
    }

    // Close the file
    file.close();

    // Print the results
    if (count == 0) {
        cout << "The search word '" << search_word << "' was not found in the file." << endl;
    } else {
        cout << "The search word '" << search_word << "' appeared " << count << " time(s) in the file." << endl;
    }

    return 0;
}
```

